export const tagCfg={GF:{label:"GF",color:"var(--gl)"},V:{label:"V",color:"var(--gm)"},VG:{label:"VG",color:"var(--terra)"}};

// Dietary filters. Note: vegan (VG) items are also vegetarian, so "Vegetarian" matches V OR VG.
export const dietFilters=[{key:"VG",label:"Vegan"},{key:"V",label:"Vegetarian"},{key:"GF",label:"Gluten-Free"}];
export const matchesDiet=(item,active)=>active.every(f=>
  f==="V"?(item.tags?.includes("V")||item.tags?.includes("VG")):item.tags?.includes(f));

// Allergen data keyed by dish name (same pattern as SPOTLIGHT_IMAGES). Shown on the dish as "<allergen> included".
// Only confirmed dishes tagged for now — full accuracy pass across all items is pending.
const ALLERGENS={
  "Muhammarah":["walnuts"],
  "Lamb Ouzi Royale":["nuts"],
};
const NUT_WORDS=["nuts","walnuts","pine nuts","almonds","pistachios","cashews","peanuts","hazelnuts"];
export const allergyFilters=[{key:"nuts",label:"Nuts",match:a=>NUT_WORDS.includes(a)}];
// Items may carry their own allergens array; otherwise fall back to the name-keyed map.
export const itemAllergens=item=>item.allergens||ALLERGENS[item.name]||[];
// An item passes when it contains none of the active (excluded) allergens.
export const matchesAllergy=(item,activeKeys)=>activeKeys.every(k=>{
  const af=allergyFilters.find(x=>x.key===k);return af?!itemAllergens(item).some(af.match):true;});

export function useInView(o={}){const[v,s]=useState(false);const r=useRef(null);
  useEffect(()=>{const el=r.current;if(!el)return;const ob=new IntersectionObserver(([e])=>{
    if(e.isIntersecting){s(true);ob.unobserve(el);}},{threshold:.1,...o});ob.observe(el);
    return()=>ob.disconnect();},[]);return[r,v];}

export function AnimatedItem({children,delay=0}){const[r,v]=useInView();
  return <div ref={r} style={{opacity:v?1:0,transform:v?"translateY(0)":"translateY(24px)",
    transition:`opacity .65s cubic-bezier(.16,1,.3,1) ${delay}s, transform .65s cubic-bezier(.16,1,.3,1) ${delay}s`}}>{children}</div>;}

function SpotlightDish({item,index}){
  const[hovered,setHovered]=useState(false);
  const[mouse,setMouse]=useState({x:0,y:0});
  const cardRef=useRef(null);
  const[ref,vis]=useInView();
  const imgSrc=SPOTLIGHT_IMAGES[item.name]||item.image_url;
  const handleMove=useCallback((e)=>{if(!cardRef.current)return;
    const r=cardRef.current.getBoundingClientRect();
    setMouse({x:(e.clientX-r.left)/r.width-.5,y:(e.clientY-r.top)/r.height-.5});},[]);
  if(!imgSrc)return <MenuItem item={item} index={index}/>;
  return <div ref={ref} style={{opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(30px)",
    transition:`opacity .8s cubic-bezier(.16,1,.3,1) ${index*.1}s, transform .8s cubic-bezier(.16,1,.3,1) ${index*.1}s`}}>
    <div ref={cardRef} onMouseEnter={()=>setHovered(true)} onMouseLeave={()=>{setHovered(false);setMouse({x:0,y:0});}}
      onMouseMove={handleMove} style={{borderRadius:"18px",overflow:"hidden",position:"relative",height:"320px",cursor:"default",
        boxShadow:hovered?"0 30px 60px rgba(43,61,43,.18),0 0 0 1px rgba(184,134,11,.15)":"0 8px 24px rgba(43,61,43,.08)",
        transition:"box-shadow .5s cubic-bezier(.16,1,.3,1)",border:"1px solid var(--bs)"}}>
      <div style={{position:"absolute",inset:"-20px",
        transform:`translate(${mouse.x*20}px,${mouse.y*20}px) scale(${hovered?1.08:1.02})`,
        transition:hovered?"transform .1s ease-out":"transform .6s cubic-bezier(.16,1,.3,1)"}}>
        <img src={imgSrc} alt={item.name} style={{width:"100%",height:"100%",objectFit:"cover",
          filter:hovered?"brightness(1.05)":"brightness(.92)"}}/></div>
      <div style={{position:"absolute",inset:0,
        background:hovered?"linear-gradient(180deg,transparent 30%,rgba(12,10,9,.5) 70%,rgba(12,10,9,.85) 100%)"
          :"linear-gradient(180deg,transparent 20%,rgba(12,10,9,.4) 60%,rgba(12,10,9,.82) 100%)",transition:"background .5s ease"}}/>
      <div style={{position:"absolute",top:0,left:0,right:0,height:"2px",
        background:hovered?"linear-gradient(90deg,transparent,rgba(184,134,11,.6),transparent)":"transparent",transition:"all .4s ease"}}/>
      {item.is_spotlight&&<div style={{position:"absolute",top:"20px",left:"20px",opacity:vis?1:0,transform:vis?"translateX(0)":"translateX(-10px)",
        transition:"all .6s cubic-bezier(.16,1,.3,1) .3s"}}>
        <span style={{fontFamily:"'Work Sans',sans-serif",fontSize:"9px",fontWeight:600,letterSpacing:".15em",textTransform:"uppercase",
          color:"rgba(255,255,255,.7)",padding:"5px 12px",borderRadius:"100px",
          background:"rgba(255,255,255,.1)",backdropFilter:"blur(8px)",border:"1px solid rgba(255,255,255,.12)"}}>Signature</span></div>}
      <div style={{position:"absolute",bottom:0,left:0,right:0,padding:"28px 28px 24px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end"}}>
          <div>
            <h3 style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"32px",fontWeight:500,color:"#F5F0E6",
              letterSpacing:".02em",lineHeight:1.1,marginBottom:"8px",textShadow:"0 2px 8px rgba(0,0,0,.3)",
              transform:hovered?"translateY(-2px)":"translateY(0)",transition:"transform .4s cubic-bezier(.16,1,.3,1)"}}>{item.name}</h3>
            <p style={{fontFamily:"'Work Sans',sans-serif",fontSize:"13px",fontWeight:300,color:"rgba(245,240,230,.7)",
              lineHeight:1.5,maxWidth:"400px",opacity:hovered?1:.85,transition:"opacity .4s ease"}}>{item.description}</p>
            {(item.tags?.length>0||itemAllergens(item).length>0)&&<div style={{display:"flex",gap:"6px",marginTop:"8px",flexWrap:"wrap",alignItems:"center"}}>
              {item.tags?.map(t=>tagCfg[t]?<span key={t} style={{fontSize:"9px",fontWeight:500,letterSpacing:".08em",padding:"2px 8px",
                borderRadius:"20px",border:"1px solid rgba(245,240,230,.2)",color:"rgba(245,240,230,.6)",textTransform:"uppercase"}}>{tagCfg[t].label}</span>:null)}
              <AllergenNote item={item} dark/></div>}
          </div>
          <span style={{fontFamily:"'Bodoni Moda',serif",fontSize:"28px",fontWeight:400,fontStyle:"italic",color:"var(--gold)",flexShrink:0,
            textShadow:"0 2px 8px rgba(0,0,0,.3)",transform:hovered?"translateY(-3px) scale(1.05)":"translateY(0) scale(1)",
            transition:"transform .4s cubic-bezier(.16,1,.3,1)"}}>{item.price}</span>
        </div></div></div></div>;}

export function AllergenNote({item,dark}){const a=itemAllergens(item);if(!a.length)return null;
  const txt=a.map(x=>x.charAt(0).toUpperCase()+x.slice(1)+" included").join(" · ");
  return <span style={{display:"inline-flex",alignItems:"center",gap:"5px",fontFamily:"'Work Sans',sans-serif",
    fontSize:"10px",fontWeight:500,letterSpacing:".05em",padding:"3px 10px",borderRadius:"20px",
    color:dark?"#F0C8A0":"var(--terra)",border:`1px solid ${dark?"rgba(240,200,160,.35)":"rgba(184,92,56,.28)"}`,
    background:dark?"rgba(184,92,56,.18)":"rgba(184,92,56,.06)"}}>⚠ {txt}</span>;}

function MenuItem({item,index}){const[h,setH]=useState(false);
  return <AnimatedItem delay={index*.07}><div onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{
    padding:"22px 26px",background:h?"var(--card-h)":"var(--card)",borderRadius:"14px",
    border:`1px solid ${h?"rgba(184,134,11,.18)":"var(--bs)"}`,transition:"all .4s cubic-bezier(.16,1,.3,1)",
    transform:h?"translateY(-3px)":"translateY(0)",boxShadow:h?"var(--sh)":"var(--ss)",cursor:"default",position:"relative",overflow:"hidden"}}>
    <div style={{position:"absolute",top:0,left:0,right:0,height:"2px",zIndex:2,
      background:h?"linear-gradient(90deg,transparent,var(--gold),transparent)":"transparent",transition:"all .4s ease",borderRadius:"14px 14px 0 0"}}/>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:"8px"}}>
      <div style={{display:"flex",alignItems:"center",gap:"8px",flex:1,flexWrap:"wrap"}}>
        <h3 style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"21px",fontWeight:600,
          color:h?"var(--gd)":"var(--tp)",transition:"color .3s ease"}}>{item.name}</h3>
        {item.tags?.map(t=>tagCfg[t]?<span key={t} style={{fontSize:"9px",fontWeight:600,letterSpacing:".08em",padding:"2px 7px",
          borderRadius:"20px",border:`1px solid ${tagCfg[t].color}33`,color:tagCfg[t].color,textTransform:"uppercase"}}>{tagCfg[t].label}</span>:null)}</div>
      <span style={{fontFamily:"'Bodoni Moda',serif",fontSize:"19px",fontWeight:400,fontStyle:"italic",
        color:"var(--gold)",marginLeft:"16px",flexShrink:0}}>{item.price}</span></div>
    <p style={{fontFamily:"'Work Sans',sans-serif",fontSize:"13.5px",fontWeight:300,color:"var(--ts)",lineHeight:1.6}}>{item.description}</p>
    {itemAllergens(item).length>0&&<div style={{marginTop:"10px"}}><AllergenNote item={item}/></div>}
  </div></AnimatedItem>;}

export function SectionHeader({category}){const[r,v]=useInView();
  return <div ref={r} style={{marginBottom:"28px"}}><div style={{display:"flex",alignItems:"center",gap:"20px",
    opacity:v?1:0,transform:v?"translateX(0)":"translateX(-20px)",transition:"all .8s cubic-bezier(.16,1,.3,1)"}}>
    <h2 style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"clamp(28px,5vw,38px)",fontWeight:400,
      color:"var(--gd)",letterSpacing:".03em",whiteSpace:"nowrap"}}>{category.label}</h2>
    <div style={{flex:1,height:"1px",background:"linear-gradient(90deg,var(--gm),transparent)",opacity:.2,
      transform:v?"scaleX(1)":"scaleX(0)",transformOrigin:"left",transition:"transform 1s cubic-bezier(.16,1,.3,1) .3s"}}/></div></div>;}

function LoadingSkeleton(){return <div style={{maxWidth:"800px",margin:"0 auto",padding:"48px 24px"}}>
  {[1,2,3,4,5].map(i=><div key={i} style={{height:"80px",borderRadius:"14px",marginBottom:"12px",
    background:"linear-gradient(90deg,rgba(43,61,43,.04),rgba(43,61,43,.08),rgba(43,61,43,.04))",
    backgroundSize:"200% 100%",animation:"shimmer 1.5s infinite"}}/>)}</div>;}

export default function AyatMenu(){
  const[categories,setCategories]=useState([]);
  const[menuItems,setMenuItems]=useState({});
  const[loading,setLoading]=useState(true);
  const[error,setError]=useState(null);
  const[active,setActive]=useState("");
  const[heroVis,setHeroVis]=useState(false);
  const[diet,setDiet]=useState([]);
  const[allergy,setAllergy]=useState([]);
  const sR=useRef({});const nR=useRef({});const scR=useRef(null);

  const toggleDiet=useCallback(k=>setDiet(d=>d.includes(k)?d.filter(x=>x!==k):[...d,k]),[]);
  const toggleAllergy=useCallback(k=>setAllergy(a=>a.includes(k)?a.filter(x=>x!==k):[...a,k]),[]);
  const anyFilter=diet.length>0||allergy.length>0;
  const clearAll=useCallback(()=>{setDiet([]);setAllergy([]);},[]);

  const filteredItems=useMemo(()=>{
    if(!diet.length&&!allergy.length)return menuItems;
    const out={};
    for(const slug in menuItems)out[slug]=menuItems[slug].filter(it=>matchesDiet(it,diet)&&matchesAllergy(it,allergy));
    return out;
  },[menuItems,diet,allergy]);
  const visibleCats=useMemo(()=>categories.filter(c=>(filteredItems[c.slug]?.length||0)>0),[categories,filteredItems]);
  const totalShown=useMemo(()=>visibleCats.reduce((n,c)=>n+filteredItems[c.slug].length,0),[visibleCats,filteredItems]);

  useEffect(()=>{
    async function fetchMenu(){
      try{
        const[catRes,itemRes]=await Promise.all([
          supabase.from('categories').select('*').order('sort_order'),
          supabase.from('menu_items').select('*').eq('is_active',true).order('sort_order'),
        ]);
        if(catRes.error)throw catRes.error;
        if(itemRes.error)throw itemRes.error;
        setCategories(catRes.data);
        if(catRes.data.length>0)setActive(catRes.data[0].slug);
        const grouped={};
        catRes.data.forEach(c=>{grouped[c.slug]=[];});
        itemRes.data.forEach(item=>{if(grouped[item.category_slug])grouped[item.category_slug].push(item);});
        setMenuItems(grouped);
      }catch(err){console.error('Menu fetch error:',err);setError(err.message);}
      finally{setLoading(false);}
    }
    fetchMenu();
  },[]);

  useEffect(()=>{setTimeout(()=>setHeroVis(true),100);},[]);

  useEffect(()=>{
    const f=()=>{const c=scR.current;if(!c||categories.length===0)return;let cur=categories[0].slug;
      for(const cat of categories){const el=sR.current[cat.slug];if(el&&el.offsetTop-c.offsetTop<=c.scrollTop+180)cur=cat.slug;}
      setActive(cur);};
    const c=scR.current;if(c){c.addEventListener("scroll",f,{passive:true});return()=>c.removeEventListener("scroll",f);}
  },[categories]);

  useEffect(()=>{const b=nR.current[active];if(b)b.scrollIntoView({behavior:"smooth",inline:"center",block:"nearest"});},[active]);

  useEffect(()=>{if(visibleCats.length>0&&!visibleCats.some(c=>c.slug===active))setActive(visibleCats[0].slug);},[visibleCats,active]);

  const goTo=useCallback(id=>{const el=sR.current[id];const c=scR.current;
    if(el&&c)c.scrollTo({top:el.offsetTop-c.offsetTop-120,behavior:"smooth"});},[]);

  return <div ref={scR} style={{height:"100vh",overflowY:"auto",overflowX:"hidden",background:"var(--bg)",position:"relative"}}>
    <style>{CSS}</style>
    <div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0,
      background:"radial-gradient(ellipse at 20% 0%,rgba(43,61,43,.03) 0%,transparent 60%),radial-gradient(ellipse at 80% 100%,rgba(184,134,11,.03) 0%,transparent 60%)"}}/>

    <header style={{minHeight:"46vh",display:"flex",flexDirection:"column",justifyContent:"center",
      alignItems:"center",textAlign:"center",padding:"32px 24px 28px",position:"relative",zIndex:1}}>
      <div style={{opacity:heroVis?1:0,transform:heroVis?"translateY(0) scale(1)":"translateY(20px) scale(.9)",
        transition:"all 1.2s cubic-bezier(.16,1,.3,1) .3s",marginBottom:"14px"}}><AyatLogo width={150}/></div>
      <div style={{opacity:heroVis?1:0,transition:"opacity 1s ease .8s",marginBottom:"16px"}}>
        <TatreezDivider color="var(--gd)" opacity={.25}/></div>
      <div style={{opacity:heroVis?1:0,transform:heroVis?"translateY(0)":"translateY(20px)",
        transition:"all 1s cubic-bezier(.16,1,.3,1) 1s"}}>
        <p style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"clamp(17px,3vw,22px)",fontWeight:300,
          fontStyle:"italic",color:"var(--ts)",maxWidth:"380px",lineHeight:1.5}}>
          Rooted in za'atar traditions, reimagined for today</p></div>
      <div style={{opacity:heroVis?1:0,transition:"opacity 1.2s ease 1.2s",marginTop:"20px"}}>
        <p style={{fontFamily:"'Work Sans',sans-serif",fontSize:"11px",fontWeight:500,
          letterSpacing:".3em",textTransform:"uppercase",color:"var(--gold)"}}>Palestinian Soul Food</p></div>
      <div style={{opacity:heroVis?1:0,transition:"opacity 1.5s ease 1.4s",marginTop:"28px",
        display:"flex",gap:"8px",flexWrap:"wrap",justifyContent:"center"}}>
        {["Bushwick"].map(l=>
          <span key={l} style={{fontFamily:"'Work Sans',sans-serif",fontSize:"9px",fontWeight:400,
            letterSpacing:".15em",textTransform:"uppercase",color:"var(--tm)",
            padding:"5px 12px",borderRadius:"100px",border:"1px solid var(--bs)"}}>{l}</span>)}</div>
      <div style={{marginTop:"32px",
        opacity:heroVis?1:0,transition:"opacity 1.5s ease 1.6s",display:"flex",flexDirection:"column",alignItems:"center",gap:"6px"}}>
        <p style={{fontFamily:"'Work Sans',sans-serif",fontSize:"10px",letterSpacing:".2em",
          textTransform:"uppercase",color:"var(--tm)"}}>Our Menu</p>
        <div style={{width:"1px",height:"28px",background:"linear-gradient(180deg,var(--gm),transparent)",
          opacity:.3,animation:"pulse 2s ease-in-out infinite"}}/></div>
    </header>

    {categories.length>0&&<nav style={{position:"sticky",top:0,zIndex:50,padding:"0 24px",
      backdropFilter:"blur(20px) saturate(1.4)",WebkitBackdropFilter:"blur(20px) saturate(1.4)",
      background:"rgba(245,240,230,.88)",borderBottom:"1px solid var(--bs)"}}>
      <div style={{maxWidth:"800px",margin:"0 auto",overflowX:"auto",display:"flex",gap:"2px",
        padding:"10px 0",scrollbarWidth:"none",msOverflowStyle:"none"}}>
        {visibleCats.map(c=><button key={c.slug} ref={el=>nR.current[c.slug]=el} onClick={()=>goTo(c.slug)}
          style={{fontFamily:"'Work Sans',sans-serif",fontSize:"11px",fontWeight:active===c.slug?500:400,
            letterSpacing:".1em",textTransform:"uppercase",color:active===c.slug?"var(--gd)":"var(--tm)",
            background:active===c.slug?"var(--gp)":"transparent",
            border:active===c.slug?"1px solid rgba(43,61,43,.1)":"1px solid transparent",
            padding:"8px 16px",borderRadius:"100px",cursor:"pointer",
            transition:"all .3s ease",whiteSpace:"nowrap",flexShrink:0}}>{c.label}</button>)}</div></nav>}

    <main style={{maxWidth:"800px",margin:"0 auto",padding:"48px 24px 120px",position:"relative",zIndex:1}}>
      {loading&&<LoadingSkeleton/>}
      {error&&<div style={{textAlign:"center",padding:"40px",color:"var(--terra)"}}><p>Could not load the menu. Please try refreshing.</p></div>}
      {!loading&&!error&&<>
        <AnimatedItem><p style={{fontFamily:"'Work Sans',sans-serif",fontSize:"12px",color:"var(--tm)",
          textAlign:"center",marginBottom:"28px",letterSpacing:".03em"}}>
          All meats are halal</p></AnimatedItem>
        <AnimatedItem><div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:"8px",
          flexWrap:"wrap",marginBottom:"48px"}}>
          <span style={{fontFamily:"'Work Sans',sans-serif",fontSize:"10px",fontWeight:500,letterSpacing:".12em",
            textTransform:"uppercase",color:"var(--tm)",flexShrink:0}}>Dietary</span>
          {dietFilters.map(f=>{const on=diet.includes(f.key);return <button key={f.key} onClick={()=>toggleDiet(f.key)}
            style={{fontFamily:"'Work Sans',sans-serif",fontSize:"11px",fontWeight:on?600:400,letterSpacing:".04em",
              color:on?"var(--gd)":"var(--tm)",background:on?"var(--gp)":"transparent",
              border:`1px solid ${on?"rgba(43,61,43,.18)":"var(--bs)"}`,padding:"6px 14px",borderRadius:"100px",
              cursor:"pointer",transition:"all .3s ease",whiteSpace:"nowrap"}}>{on?"✓ ":""}{f.label}</button>;})}
          <span style={{width:"1px",height:"18px",background:"var(--bs)",flexShrink:0}}/>
          <span style={{fontFamily:"'Work Sans',sans-serif",fontSize:"10px",fontWeight:500,letterSpacing:".12em",
            textTransform:"uppercase",color:"var(--tm)",flexShrink:0}}>Allergies</span>
          {allergyFilters.map(f=>{const on=allergy.includes(f.key);return <button key={f.key} onClick={()=>toggleAllergy(f.key)}
            style={{fontFamily:"'Work Sans',sans-serif",fontSize:"11px",fontWeight:on?600:400,letterSpacing:".04em",
              color:on?"var(--terra)":"var(--tm)",background:on?"rgba(184,92,56,.08)":"transparent",
              border:`1px solid ${on?"rgba(184,92,56,.28)":"var(--bs)"}`,padding:"6px 14px",borderRadius:"100px",
              cursor:"pointer",transition:"all .3s ease",whiteSpace:"nowrap"}}>{on?"✕ ":""}{f.label}</button>;})}
          {anyFilter&&<button onClick={clearAll} style={{fontFamily:"'Work Sans',sans-serif",fontSize:"11px",
            fontWeight:400,color:"var(--terra)",background:"transparent",border:"none",padding:"6px 8px",
            cursor:"pointer",letterSpacing:".04em"}}>Clear</button>}
          {anyFilter&&<span style={{fontFamily:"'Work Sans',sans-serif",fontSize:"10px",color:"var(--tm)",
            flexShrink:0}}>· {totalShown} {totalShown===1?"dish":"dishes"}</span>}
        </div></AnimatedItem>
        {totalShown===0&&<div style={{textAlign:"center",padding:"60px 20px"}}>
          <p style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"22px",fontStyle:"italic",color:"var(--tm)",marginBottom:"16px"}}>
            No dishes match those filters.</p>
          <button onClick={clearAll} style={{fontFamily:"'Work Sans',sans-serif",fontSize:"11px",
            letterSpacing:".1em",textTransform:"uppercase",color:"var(--gd)",background:"var(--gp)",
            border:"1px solid rgba(43,61,43,.1)",padding:"10px 20px",borderRadius:"100px",cursor:"pointer"}}>Clear filters</button></div>}
        {visibleCats.map((cat,ci)=><section key={cat.slug} ref={el=>sR.current[cat.slug]=el} style={{marginBottom:"64px"}}>
          <SectionHeader category={cat}/>
          <div style={{display:"flex",flexDirection:"column",gap:"10px"}}>
            {filteredItems[cat.slug]?.map((item,i)=>
              (item.is_spotlight||SPOTLIGHT_IMAGES[item.name])?<SpotlightDish key={item.id} item={item} index={i}/>
                :<MenuItem key={item.id} item={item} index={i}/>)}</div>
          {ci<visibleCats.length-1&&<AnimatedItem delay={.2}><div style={{paddingTop:"40px"}}><TatreezDivider/></div></AnimatedItem>}
        </section>)}
        <AnimatedItem><footer style={{textAlign:"center",paddingTop:"40px",borderTop:"1px solid var(--bs)"}}>
          <div style={{marginBottom:"16px",opacity:.5}}><AyatLogo width={130}/></div>
          <p style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"15px",fontWeight:300,fontStyle:"italic",
            color:"var(--tm)",lineHeight:1.8,maxWidth:"340px",margin:"0 auto 12px"}}>
            At our table, every guest becomes family, and every dish comes with a story to be shared.</p>
          <a href="/catering" style={{display:"inline-block",fontFamily:"'Work Sans',sans-serif",fontSize:"11px",
            fontWeight:500,letterSpacing:".15em",textTransform:"uppercase",color:"var(--gd)",textDecoration:"none",
            padding:"10px 22px",borderRadius:"100px",border:"1px solid var(--bs)",marginTop:"8px"}}>View Catering Menu</a>
          <p style={{fontFamily:"'Work Sans',sans-serif",fontSize:"10px",letterSpacing:".15em",
            textTransform:"uppercase",color:"var(--tm)",opacity:.5,marginTop:"20px"}}>ayatbushwick.menu</p>
        </footer></AnimatedItem></>}
    </main></div>;}
